insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('tsavo-kenya', '05A', 'Tsavo National Park (East + West)', 'Kenya', 'Kenya''s great red wilderness', 'live', 'verified', 'elephant', 'Kenya — Tsavo', '{"safari","ultra","romance","adventure","deepdive"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'core', '{"key_facts":["Kenya''s largest + oldest park - Tsavo East + West ~22,000 km2 (Tsavo East 13,747 km2), ~4% of Kenya; the great red wilderness of famous terracotta ''red elephants'' (dust-bathed in iron-rich soil)","A full Big Five park (unlike Amboseli): black rhino at the Ngulia Rhino Sanctuary (Tsavo West) + the maneless Tsavo lions; Mzima Springs crystal pools with an underwater hippo/croc observation chamber; Lugard Falls (Galana River)","The legend of the Man-Eaters of Tsavo (1898 lions that halted the Kenya-Uganda railway); on the historic Nairobi-Mombasa route","The uncrowded, BETTER-VALUE big-park alternative to the Mara (whose fees rose + circuits crowd); entry $80/non-resident; road 4-5h / SGR railway / charter from Nairobi; a natural Nairobi<->coast stopover","US L2 Exercise Increased Caution (elevated risk Nairobi/urban, not Tsavo); YF NUANCE: CDC recommends the yellow-fever vaccine for Taita-Taveta County (Tsavo) - treat YF as recommended here; malaria prophylaxis advised","Sold via KATO-member Kenya safari DMCs 15-25% - IATAN/host-gated, CLIA has NO Africa representation; KWS fees non-commissionable; KES (~129/USD) + M-Pesa but safari quoted USD; eTA required; AMREF for the size/remoteness"],"safety":{"emergency":"999 / 112 / 911; Kenya Red Cross ambulance 1199 (often more reliable nationwide); AMREF Flying Doctors for bush evac","hospital":"Vast/remote - AMREF Flying Doctors (~$40 pp/30d) + travel-medical insurance; nearest referral Voi/Mombasa/Nairobi","advisory_level":"L2","malaria":"prophylaxis advised (Tsavo qualifies, chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory if arriving from a risk country - AND CDC recommends the vaccine for Taita-Taveta County (Tsavo)","activity_note":"L2 disclose (elevated risk is Nairobi/urban, not Tsavo). Dangerous game at close range (lion, elephant, hippo + croc at Mzima) - stay in the vehicle, view Mzima from the boardwalk/chamber only. VASTNESS: ~22,000 km2 sparsely-roaded - breakdowns far from help, experienced operator + fuel/water + evac cover. YF recommended (Taita-Taveta). Remote - carry AMREF evac + insurance"},"timing":{"peak":"Jun-Oct + Jan-Feb (dry - bush thins, wildlife at water, red elephants + Mzima easiest)","shoulder":"Nov + Mar (quieter, softer rates)","green":"Apr-May (long rains - lush, birdlife, quietest, cheapest)","booking_lead":"lodges + Kenya-circuit 2-5 mo (Jun-Oct + Jan-Feb; less crunch than the Mara); shoulder/green 1-3 mo","off_season_specials":"Apr-May green-season value + birding; position as the uncrowded cheaper big park + Nairobi<->coast stopover; combine Amboseli or Mombasa/Diani beach","event_peaks":"Jun-Oct + Christmas/NY + Easter; coast-combo demand with beach season","campaign_start":"Jun-Oct + Jan-Feb 3-5 mo out; value-vs-the-Mara + green birding by prior Sep-Nov; bundle Tsavo + Amboseli + coast (southern-Kenya loop)"},"jewels":[{"name":"The red elephants of Tsavo East","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$350-1,500/pp/day","timing":"Jun-Oct + Jan-Feb; dry best","commission_path":"safari DMC 15-25%","draw_rank":1,"hook":"great herds of terracotta-red elephants across vast open plains, with far fewer vehicles than the Mara","si":"safari","blurb":"great herds of terracotta-red elephants across vast open plains, with far fewer vehicles than the Mara","when":"Jun-Oct + Jan-Feb; dry best","commission":"safari DMC 15-25%"},{"name":"Big Five + black rhino at Ngulia (Tsavo West)","si_tag":"safari","status":"live","tier":"comfort","price_band":"~$400-1,600/pp/day","timing":"Jun-Oct + Jan-Feb","commission_path":"safari DMC 15-25%","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the maneless Tsavo lions, leopard, buffalo and elephant — plus the critically endangered black rhino of the Ngulia Rhino Sanctuary","si":"safari","blurb":"the maneless Tsavo lions, leopard, buffalo and elephant — plus the critically endangered black rhino of the Ngulia Rhino Sanctuary","when":"Jun-Oct + Jan-Feb","commission":"safari DMC 15-25%"},{"name":"Mzima Springs + the underwater chamber","si_tag":"globaladv","status":"live","tier":"essential","price_band":"~$30-120/pp","timing":"Jun-Oct + Jan-Feb","commission_path":"DMC/camp","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"crystal Chyulu-fed pools alive with hippos and crocodiles, watched from a famous underwater observation chamber","si":"adventure","blurb":"crystal Chyulu-fed pools alive with hippos and crocodiles, watched from a famous underwater observation chamber","when":"Jun-Oct + Jan-Feb","commission":"DMC/camp"},{"name":"The Man-Eaters of Tsavo","si_tag":"deepdive","status":"future","tier":"essential","price_band":"on application","timing":"Jun-Oct + Jan-Feb","commission_path":"DMC/venue","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The 1898 lions that halted the Kenya–Uganda railway before Lt-Col Patterson shot them — Tsavo lies on the historic Nairobi–Mombasa route","si":"deepdive","blurb":"The 1898 lions that halted the Kenya–Uganda railway before Lt-Col Patterson shot them — Tsavo lies on the historic Nairobi–Mombasa route","when":"Jun-Oct + Jan-Feb","commission":"DMC/venue"},{"name":"A Finch Hattons / Kilaguni honeymoon","si_tag":"ultra","status":"live","tier":"premier","price_band":"~$400-1,500+/night all-in","timing":"standing; peak 2-5 mo","commission_path":"consortia/Virtuoso + DMC","draw_rank":1,"hook":"Tsavo West''s grand lodges — Finch Hattons'' spring-fed luxury tents, Kilaguni Serena''s waterhole veranda under the Chyulu Hills — private, wild and quiet; honeymoon-grade","si":"ultra","blurb":"Tsavo West''s grand lodges — Finch Hattons'' spring-fed luxury tents, Kilaguni Serena''s waterhole veranda under the Chyulu Hills — private, wild and quiet; honeymoon-grade","when":"standing; peak 2-5 mo","commission":"consortia/Virtuoso + DMC"},{"name":"A Tsavo bush honeymoon","si_tag":"romance","status":"live","tier":"premier","price_band":"on application","timing":"Jun-Oct + Jan-Feb","commission_path":"consortia/host","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Jun-Oct + Jan-Feb","commission":"consortia/host"}],"faq":[{"q":"Is Tsavo safe to visit right now?","a":"Yes - freely bookable. Kenya is US Level 2 (Exercise Increased Caution) - the elevated risk is in Nairobi/urban areas, not Tsavo; on safari with a licensed operator the practical exposure is the wildlife, not crime. We disclose the L2.","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for in Tsavo?","a":"Vastness and remoteness. At ~22,000 km2 of sparsely-roaded wilderness, a breakdown or emergency is far from help - travel with an experienced operator and carry AMREF Flying Doctors (~$40 pp/30 days) + travel-medical insurance. Dangerous game (lion, elephant, hippo and croc at Mzima) - stay in the vehicle and follow your guide.","source":"en.wikipedia.org","si_tag":"safety"},{"q":"Do I need the yellow-fever vaccine for Tsavo?","a":"Note the nuance: while YF is otherwise only mandatory arriving from a risk country, CDC specifically recommends the yellow-fever vaccine for Taita-Taveta County, which is Tsavo - so plan for YF as recommended for this park, plus malaria prophylaxis.","source":"cdc.gov","si_tag":"safety"},{"q":"When is the best time to visit Tsavo?","a":"Jun-Oct and Jan-Feb (dry) - bush thins, wildlife concentrates at water, and the red elephants and Mzima hippos are easiest to find. The green rains bring lush scenery, birdlife and lower rates.","source":"tsavonationalparkkenya.com","si_tag":"safari"},{"q":"Tsavo East or Tsavo West - which?","a":"Tsavo East is the classic - vast open plains and the red-elephant herds; Tsavo West is more varied - volcanic terrain, Mzima Springs, and Ngulia''s black rhino. Many itineraries do both, or pair Tsavo with Amboseli or the coast.","source":"safaritravelplus.com","si_tag":"safari"},{"q":"Do I need a visa for Kenya?","a":"An eTA (Kenya replaced visas with the eTA in 2024 - apply at least 2 weeks ahead; required for all visitors). Currency is the Kenyan shilling with M-Pesa everywhere, but safari is quoted in USD.","source":"en.wikipedia.org","si_tag":"safari"}],"seo":{"meta_title":"Tsavo Safari Guide: Red Elephants, Big Five (Ngulia Rhino), Mzima Springs & Best Time","meta_description":"Plan a Tsavo safari - Kenya''s largest, oldest and least-crowded big park: the famous red elephants, a full Big Five with black rhino at Ngulia, the underwater window of Mzima Springs, the legend of the Man-Eaters, better value than the Mara - with real safety (YF-recommended), timing and cost.","slug":"tsavo-kenya","primary_keyword":"Tsavo safari","long_tail":["Tsavo red elephants","Tsavo East vs West","Ngulia rhino sanctuary","Mzima Springs Tsavo","Man-Eaters of Tsavo","best time to visit Tsavo","is Tsavo safe"],"search_language":"sw","local_keywords":["Tsavo","tembo wekundu","Chemchem za Mzima","faru mweusi","simba wa Tsavo","Maporomoko ya Lugard"],"hreflang":["en","sw"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-31"},"booking":{"bin":"freely_bookable","level":"L2","codes":["exercise-increased-caution","crime","urban-unrest"],"consent_flow":false,"book_suppressed":false,"note":"Kenya US L2 Exercise Increased Caution - elevated risk in Nairobi/urban areas, not Tsavo; safe licensed-operator safari. Disclose L2. NOTE: CDC recommends yellow-fever vaccine for Taita-Taveta County (Tsavo). Re-verify each cycle."},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; SAFARI is the launch/demo SI - primary safari not globaladv; Mzima Springs/Lugard Falls/walks = globaladv; Man-Eaters/railway history = deepdive; Tsavo IS a Big Five park (Ngulia black rhino); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"safari","name":"safari","status":"live","note":"red elephants + Big Five incl. black rhino (Ngulia)"},{"si":"ultra","name":"ultra","status":"live","note":"Finch Hattons / Kilaguni"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"live"},{"si":"globaladv","name":"adventure","status":"live","note":"Mzima Springs underwater chamber, Lugard Falls"},{"si":"deepdive","name":"deepdive","status":"future","note":"the Man-Eaters of Tsavo / railway history"}],"ultra":[{"name":"Finch Hattons Luxury Tented Camp - Tsavo''s apex stay","why_ultra":"spring-fed colonial-glamour tents under the Chyulu Hills, spa + private guiding in a vast wilderness","earning":"consortia/Virtuoso","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$900-1,800+/night"},{"name":"A private Tsavo East + West + Ngulia-rhino week","why_ultra":"exclusive-vehicle safari across the red-elephant plains, Mzima Springs and the black-rhino sanctuary, privately guided","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"},{"name":"A southern-Kenya bush-and-beach week (Tsavo + Amboseli + Diani)","why_ultra":"red elephants + rhino, elephants-and-Kili, then the Indian-Ocean coast, private-guided throughout","earning":"DMC/consortia","virtuoso_value_add":false,"mor":"commissionable","tier":"ultra","price_band":"on application"}],"source_verified":"2026-07-31","hero":{"query":"Tsavo National Park (East + West), Kenya"},"geo":{"lat":-2.8,"lng":38.5}}'::jsonb, 19),
