  ('quirimbas-archipelago-mozambique', '06A', 'Quirimbas Archipelago', 'Mozambique', 'Some of Africa''s richest reefs and a 400-year-old Swahili', 'future', 'verified', 'oceanAerial', 'Mozambique & Coast', '{"diveglobal","tropical","culture","deepdive","adventure","ultra"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["BOOKING HOLD: entirely within Cabo Delgado Province, US Level 4 Do Not Travel (ISIS-linked ASWJ insurgency; islands occupied by militants; foreigners kidnapped; Palma 2021 attack ~1,193 killed/missing, 209 kidnapped). CONTENT-ONLY, no Book path, no waiver","~32 islands off NE Mozambique (Ibo, Matemo, Medjumbe, Vamizi, Quirimba, Rolas) inside Quirimbas National Park","Reefs among the world''s richest - Neptune''s Arm cited among the best dive sites in the world; humpback whales, whale sharks, humpback dolphins in season (all HELD)","Ibo Island: 400-year-old Swahili-Portuguese stone town, fort, silversmiths (UNESCO-tentative); barefoot-ultra islands Anantara Medjumbe + Vamizi (HELD)","MALARIA HIGH; cyclone Dec-Apr; even the gateway Pemba is high-risk; evacuation not assured","Rest of Mozambique differs - southern coast (Bazaruto, Tofo, Vilanculos, Inhambane, Maputo) is bookable and far from the conflict"],"safety":{"emergency":"police 119 (also 112); INEM ambulance 117 (non-functional in conflict zone)","hospital":"Pemba (Provincial Hospital / International SOS) - but Pemba itself is L4; evacuation not assured","advisory_level":"L4","malaria":"HIGH (prophylaxis + bite prevention essential)","yellow_fever":"required only if arriving from an endemic country","cyclone":"Dec-Apr","activity_note":"SECURITY-DOMINANT: ISIS-linked ASWJ insurgency + kidnapping is the disqualifying hazard - islands occupied, foreigners kidnapped, evacuation not assured. Marine/health hazards (HIGH malaria, cyclone, remote chamber) are secondary and moot while held. CONTENT-ONLY, no waiver.","booking_hold":true},"timing":{"booking_status":"HELD - no live demand capture while Level 4 stands (no campaigns/fire-dates)","latent_peak":"May-Nov (dry, calmer seas, best diving; humpback whales ~Jul-Oct) - IF cleared","latent_green_cyclone":"Dec-Apr (hot, wet, cyclone season)","latent_booking_lead":"remote fly-in island lodges 4-9 mo - NOT applicable while held","reverify_trigger":"check Cabo Delgado advisory status every publish cycle; booking stays suppressed until US State Dept + UK FCDO both stand down from do-not-travel","redirect":"live Mozambique demand -> Bazaruto Archipelago / Tofo / Vilanculos / Inhambane / Maputo (bookable, far from Cabo Delgado)"},"jewels":[{"name":"Neptune''s Arm + the world-class reefs","si_tag":"diveglobal","status":"held","tier":"premier","price_band":"HELD - no book path","timing":"HELD; latent May-Nov","commission_path":"none (advisory hold)","draw_rank":null,"hook":"In peacetime the diving is elite: \"Neptune''s Arm\" is cited among the best dive sites in the world","si":"diveglobal","blurb":"In peacetime the diving is elite: \"Neptune''s Arm\" is cited among the best dive sites in the world","when":"HELD; latent May-Nov","commission":"none (advisory hold)"},{"name":"Humpback whales + whale sharks in season","si_tag":"globaladv","status":"held","tier":"premier","price_band":"HELD - no book path","timing":"HELD; latent seasonal","commission_path":"none (advisory hold)","draw_rank":null,"hook":"the reefs see humpback whales on migration, whale sharks and humpback dolphins — a genuine marine-wildlife draw, all currently held. STATUS: HELD","si":"adventure","blurb":"the reefs see humpback whales on migration, whale sharks and humpback dolphins — a genuine marine-wildlife draw, all currently held. STATUS: HELD","when":"HELD; latent seasonal","commission":"none (advisory hold)"},{"name":"Ibo Island Stone Town","si_tag":"culture","status":"held","tier":"essential","price_band":"HELD - no book path","timing":"HELD","commission_path":"none (advisory hold)","draw_rank":null,"hook":"a 400-year-old Swahili-Portuguese fort town of coral-stone ruins and working silversmiths — the archipelago''s cultural heart. STATUS: HELD","si":"culture","blurb":"a 400-year-old Swahili-Portuguese fort town of coral-stone ruins and working silversmiths — the archipelago''s cultural heart. STATUS: HELD","when":"HELD","commission":"none (advisory hold)"},{"name":"The Swahili + slave-trade history of Ibo","si_tag":"deepdive","status":"held","tier":"essential","price_band":"HELD - no book path","timing":"HELD","commission_path":"none (advisory hold)","draw_rank":null,"hook":"Ibo was a Swahili-coast and Portuguese trading and slaving hub","si":"deepdive","blurb":"Ibo was a Swahili-coast and Portuguese trading and slaving hub","when":"HELD","commission":"none (advisory hold)"},{"name":"The powder-sand private islands (Medjumbe, Vamizi, Matemo)","si_tag":"tropical","status":"held","tier":"luxury","price_band":"HELD - no book path","timing":"HELD","commission_path":"none (advisory hold)","draw_rank":null,"si":"tropical","when":"HELD","commission":"none (advisory hold)"},{"name":"Anantara Medjumbe & Vamizi (barefoot-ultra)","si_tag":"ultra","status":"held","tier":"ultra","price_band":"HELD - no book path","timing":"HELD","commission_path":"none (advisory hold)","draw_rank":null,"hook":"the archipelago''s exclusive fly-in island lodges — the ultra expression of the Quirimbas","si":"ultra","blurb":"the archipelago''s exclusive fly-in island lodges — the ultra expression of the Quirimbas","when":"HELD","commission":"none (advisory hold)"}],"faq":[{"q":"Is the Quirimbas Archipelago safe to visit right now?","a":"No - and it is not bookable through TravelWell. The archipelago lies entirely in Cabo Delgado Province under a US Level 4 ''Do Not Travel'' advisory; we present it as content and suppress the Book button until the advisory clears.","source":"travel.state.gov","si_tag":"safety"},{"q":"What exactly is the danger in the Quirimbas?","a":"An active ISIS-linked insurgency (ASWJ). Armed groups have attacked villages and occupied islands in the archipelago and the mainland port of Mocimboa da Praia; foreigners have been kidnapped, and the 2021 Palma attack killed or displaced thousands. Marine and health hazards are secondary to the conflict.","source":"ctc.westpoint.edu","si_tag":"safety"},{"q":"Could I go with a private security arrangement or a waiver?","a":"No - TravelWell offers no waiver and no book path for a Level 4 zone. Evacuation from a remote island in an active-conflict setting is not assured, and even the gateway city of Pemba is high-risk. The responsible answer is to wait for the advisory to change.","source":"mz.usembassy.gov","si_tag":"safety"},{"q":"Is the rest of Mozambique off-limits too?","a":"No - this hold is Cabo Delgado-specific. Southern Mozambique (Maputo, Tofo, Vilanculos, the Bazaruto Archipelago, Inhambane) is far from the conflict and remains a bookable Indian-Ocean destination; that is where we point Mozambique demand today.","source":"gov.uk","si_tag":"safety"},{"q":"When the advisory clears, what would the Quirimbas offer?","a":"Elite diving (Neptune''s Arm and untouched reefs), humpback whales and whale sharks in season, the Swahili stone town of Ibo, and barefoot-luxury private islands (Medjumbe, Vamizi) - a world-class dive-and-heritage archipelago. All of it is held until the advisory lifts.","source":"expertafrica.com","si_tag":"diveglobal"},{"q":"What are the non-security health risks to know?","a":"Malaria is HIGH (prophylaxis + bite prevention essential), cyclone season is Dec-Apr, yellow-fever proof is needed only if arriving from an endemic country, and in-conflict medical/evacuation capacity is minimal - reinforcing the booking hold.","source":"wwwnc.cdc.gov","si_tag":"safety"}],"seo":{"meta_title":"Quirimbas Archipelago, Mozambique: World-Class Reefs & Ibo Stone Town - On Hold (Level 4)","meta_description":"The Quirimbas Archipelago - ~32 islands of world-class reefs (Neptune''s Arm), humpback whales and the 400-year-old Swahili stone town of Ibo - is currently a US Level 4 ''Do Not Travel'' zone (Cabo Delgado insurgency). What it is, why it''s held, and where to go in Mozambique instead.","slug":"quirimbas-archipelago-mozambique","primary_keyword":"Quirimbas Archipelago Mozambique","long_tail":["Quirimbas islands diving","Neptune''s Arm dive site","Ibo Island stone town","is Cabo Delgado safe","Anantara Medjumbe","Vamizi Island","Quirimbas National Park"],"search_language":"pt","local_keywords":["Arquipelago das Quirimbas","Ilha do Ibo","Parque Nacional das Quirimbas","Cabo Delgado","mergulho Quirimbas","Medjumbe","Vamizi"],"hreflang":["en","pt"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-30"},"booking":{"bin":"booking_hold","level":"L4","codes":["do-not-travel","terrorism","kidnapping","armed-conflict"],"consent_flow":true,"book_suppressed":true,"waiver":false,"note":"Cabo Delgado Province US L4 Do Not Travel (ISIS-linked ASWJ insurgency; islands occupied; kidnapping; Palma 2021). CONTENT-ONLY, Book button suppressed, no waiver. Re-verify each publish cycle. Overall Mozambique L3; Cabo Delgado carved out at L4."},"si_checklist_25":{"run_date":"2026-07-30","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; EVERY hit is HELD behind the L4 booking hold - no SI is servable while Level 4 stands; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"held"},{"si":"tropical","name":"tropical","status":"held"},{"si":"culture","name":"culture","status":"held"},{"si":"deepdive","name":"deepdive","status":"held"},{"si":"globaladv","name":"adventure","status":"held"},{"si":"ultra","name":"ultra","status":"held"}],"ultra":[{"name":"Anantara Medjumbe Private Island (HELD)","why_ultra":"an exclusive one-resort island - the ultra of the Quirimbas; documented for the day the hold lifts, sold by no one today","earning":"none while held","virtuoso_value_add":false,"mor":"n/a (L4 booking hold)","tier":"ultra","status":"HELD"},{"name":"Vamizi Island Lodge (HELD)","why_ultra":"~12 luxury beach villas over a healthy reef; barefoot-ultra, currently closed/threatened","earning":"none while held","virtuoso_value_add":false,"mor":"n/a (L4 booking hold)","tier":"ultra","status":"HELD"}],"source_verified":"2026-07-30","hero":{"query":"Quirimbas Archipelago, Mozambique"},"geo":{"lat":-12.2,"lng":40.6}}'::jsonb, 46),
