es 2-6 wk","off_season_specials":"wet-season Angkor + city; VN<->KH value cruises shoulder (operator 2026-28 discounts)","event_peaks":"Khmer New Year (~mid-Apr, Angkor busy/some closures); Water Festival Bon Om Touk (~Nov, Phnom Penh); dry cruise window Nov-Apr","campaign_start":"Dry-season Mekong+Angkor by prior spring; Nov-Apr high season by Aug; Tonle Sap high-water content by Sep; wet-season value by Apr"},"jewels":[{"name":"The Mekong cruise, Phnom Penh <-> Siem Reap","si_tag":"river","status":"live","tier":"premier","price_band":"~$2,500-7,000+/pp/week","timing":"year-round; dry Nov-Apr peak","commission_path":"cruise-line 10-16%","draw_rank":1,"hook":"the primary sell — the Cambodian leg via the Tonlé Sap, most as the up-river half of a Vietnam↔Cambodia sailing","si":"river","blurb":"the primary sell — the Cambodian leg via the Tonlé Sap, most as the up-river half of a Vietnam↔Cambodia sailing","when":"year-round; dry Nov-Apr peak","commission":"cruise-line 10-16%"},{"name":"The Tonle Sap + floating villages","si_tag":"river","status":"live","tier":"essential","price_band":"~$25-90/pp","timing":"year-round; high water Oct-Dec","commission_path":"operator/affiliate 8-15%","draw_rank":2,"hook":"Southeast Asia''s largest freshwater lake, ringed by stilt and floating villages — a boat-borne culture reached from Siem Reap","si":"river","blurb":"Southeast Asia''s largest freshwater lake, ringed by stilt and floating villages — a boat-borne culture reached from Siem Reap","when":"year-round; high water Oct-Dec","commission":"operator/affiliate 8-15%"},{"name":"The Kampong Cham / Oudong village reach","si_tag":"river","status":"live","tier":"premier","price_band":"within cruise","timing":"Nov-Apr","commission_path":"cruise-line","draw_rank":3,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the quiet mid-river stops — Oudong''s former royal capital, Kampong Tralach stilt villages, ox-cart and monastery visits","si":"river","blurb":"the quiet mid-river stops — Oudong''s former royal capital, Kampong Tralach stilt villages, ox-cart and monastery visits","when":"Nov-Apr","commission":"cruise-line"},{"name":"Angkor - the largest temple on earth","si_tag":"culture","status":"future","tier":"essential","price_band":"~$40-200 (multi-day pass + guide)","timing":"year-round","commission_path":"operator/DMC 10-15%","draw_rank":1,"timing_type":"ALWAYS-ON","hook":"Angkor Wat at sunrise, the Bayon''s faces, jungle-wrapped Ta Prohm — ~400 km² of Khmer temples, the reason cruises terminate at Siem Reap","si":"culture","blurb":"Angkor Wat at sunrise, the Bayon''s faces, jungle-wrapped Ta Prohm — ~400 km² of Khmer temples, the reason cruises terminate at Siem Reap","when":"year-round","commission":"operator/DMC 10-15%"},{"name":"Phnom Penh''s Royal Palace + Silver Pagoda","si_tag":"culture","status":"future","tier":"essential","price_band":"~$10-40","timing":"year-round","commission_path":"operator/affiliate","draw_rank":2,"timing_type":"ALWAYS-ON","hook":"the riverfront capital''s royal heart — the palace complex and the silver-tiled pagoda","si":"culture","blurb":"the riverfront capital''s royal heart — the palace complex and the silver-tiled pagoda","when":"year-round","commission":"operator/affiliate"},{"name":"An Apsara classical-dance evening","si_tag":"culture","status":"future","tier":"essential","price_band":"~$25-80/pp","timing":"Nov-Apr","commission_path":"venue/bundle","draw_rank":3,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the UNESCO-listed Khmer court dance, performed as a Siem Reap dinner show — living culture beside the ruins","si":"culture","blurb":"the UNESCO-listed Khmer court dance, performed as a Siem Reap dinner show — living culture beside the ruins","when":"Nov-Apr","commission":"venue/bundle"},{"name":"The Khmer Rouge - Tuol Sleng + the Killing Fields","si_tag":"deepdive","status":"future","tier":"essential","price_band":"~$15-80/pp","timing":"Nov-Apr","commission_path":"op/DMC 10-15%","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Phnom Penh''s Tuol Sleng and Choeung Ek — the unflinching 1975–79 history, handled with gravity","si":"deepdive","blurb":"Phnom Penh''s Tuol Sleng and Choeung Ek — the unflinching 1975–79 history, handled with gravity","when":"Nov-Apr","commission":"op/DMC 10-15%"},{"name":"Khmer cuisine + a cooking class","si_tag":"culinary","status":"future","tier":"essential","price_band":"~$20-100/pp","timing":"Nov-Apr","commission_path":"venue/DMC 10-15%","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"fish amok, Kampot pepper crab, a market-to-table class in Siem Reap or Phnom Penh — an under-sung Southeast-Asian table","si":"culinary","blurb":"fish amok, Kampot pepper crab, a market-to-table class in Siem Reap or Phnom Penh — an under-sung Southeast-Asian table","when":"Nov-Apr","commission":"venue/DMC 10-15%"},{"name":"Angkor + countryside by bike (marked routes)","si_tag":"globaladv","status":"future","tier":"essential","price_band":"~$25-90/pp","timing":"year-round","commission_path":"operator/affiliate 10-15%","draw_rank":1,"hook":"the temples and rice-paddy lanes by bicycle, plus Tonlé Sap boating — the active layer. 🚩 UXO: established/marked routes only","si":"adventure","blurb":"the temples and rice-paddy lanes by bicycle, plus Tonlé Sap boating — the active layer. 🚩 UXO: established/marked routes only","when":"year-round","commission":"operator/affiliate 10-15%"},{"name":"Angkor sunrise + a small-ship suite","si_tag":"romance","status":"future","tier":"premier","price_band":"~$3,000-7,000+/pp","timing":"dry Nov-Apr ideal","commission_path":"cruise-line/host 10-16%","draw_rank":1,"hook":"sunrise over Angkor Wat''s reflecting pools, then a 5-star small-ship suite up the Tonlé Sap — a quiet, extraordinary honeymoon arc","si":"romance","blurb":"sunrise over Angkor Wat''s reflecting pools, then a 5-star small-ship suite up the Tonlé Sap — a quiet, extraordinary honeymoon arc","when":"dry Nov-Apr ideal","commission":"cruise-line/host 10-16%"},{"name":"The low-exertion river cruise + Angkor","si_tag":"senior","status":"future","tier":"comfort","price_band":"~$2,500-5,000/pp","timing":"dry Nov-Apr ideal","commission_path":"cruise-line/DMC 10-16%","draw_rank":1,"hook":"an all-in small-ship cruise with step-managed temple touring — a rich, low-mobility itinerary, flights linking Siem Reap","si":"senior","blurb":"an all-in small-ship cruise with step-managed temple touring — a rich, low-mobility itinerary, flights linking Siem Reap","when":"dry Nov-Apr ideal","commission":"cruise-line/DMC 10-16%"}],"faq":[{"q":"Is Cambodia safe to visit right now?","a":"Yes, with disclosure - bookable at Level 2 (Exercise Increased Caution), issued 25 July 2025, driven by petty crime and landmines/UXO. The only Do-Not-Travel zone is the 50 km Thai-border strip (Level 4), which no Mekong itinerary touches.","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for in Cambodia?","a":"Landmines/UXO - the safety-spine item, avalanche-level weight. Contamination persists in provinces including Siem Reap; stay strictly on marked paths and cleared temple routes, never wander into fields or unmarked ground. Petty bag-snatch is the secondary caution.","source":"travel.state.gov","si_tag":"safety"},{"q":"Are the closed Thai borders a problem for a Mekong cruise?","a":"No. All Cambodia-Thailand land crossings are closed (2026), but the Mekong cruise enters Cambodia by river from Vietnam at Tan Chau, and Siem Reap/Phnom Penh connect by flight - so cruise itineraries are unaffected. It only matters for overland Thailand-Cambodia travel.","source":"kh.usembassy.gov","si_tag":"river"},{"q":"When is the best time to cruise the Cambodian Mekong?","a":"Roughly November-April (dry, cooler); the Tonle Sap is highest and most navigable after the wet season (Oct-Dec), when the lake and its floating villages are fullest.","source":"uniworld.com","si_tag":"river"},{"q":"Which lines cruise the Cambodian Mekong?","a":"Confirmed: Aqua Expeditions (Aqua Mekong), Pandaw, Scenic, Uniworld, CroisiEurope and Viking - most on Vietnam-Cambodia itineraries, Siem Reap to Phnom Penh via the Tonle Sap and Kampong Cham.","source":"adventure-life.com","si_tag":"river"},{"q":"Is Angkor Wat worth building the trip around?","a":"Yes - Angkor is the largest religious monument on earth and the reason most cruises terminate at Siem Reap; pair the temples with the Tonle Sap floating villages and a Phnom Penh Khmer-Rouge history day for the full Cambodian arc.","source":"adventure-life.com","si_tag":"culture"}],"seo":{"meta_title":"Cambodia Mekong Travel Guide: River Cruises, Angkor Wat & the Tonle Sap","meta_description":"Plan Cambodia''s Mekong - Phnom Penh to Siem Reap river cruises (Aqua Expeditions, Pandaw, Scenic, Uniworld), Angkor Wat, the Tonle Sap floating villages and the Khmer-Rouge history sites, with the real Level-2 safety picture.","slug":"mekong-cambodia","primary_keyword":"Cambodia Mekong travel guide","long_tail":["Cambodia Mekong river cruise Phnom Penh Siem Reap 2026","Angkor Wat sunrise","Tonle Sap floating villages","is Cambodia safe to visit 2026","Cambodia landmine safety","Aqua Mekong Cambodia"],"search_language":"km-KH","local_keywords":["Mekong Kampuchea","Angkor Wat","Tonle Sap","Phnom Penh","Siem Reap"],"hreflang":["en","km-KH"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-29"},"booking":{"bin":"book_with_disclosure","level":"L2","codes":["thai-border-50km-L4","thai-land-crossings-closed","landmine-UXO"],"advisory_updated":"2025-07-25","consent_flow":false,"note":"L2 (crime+landmines). 50km Thai-border strip = L4 (off-route). Thai land crossings closed 2026 (river cruise from Vietnam unaffected). UXO safety-spine: stay on marked paths."},"si_checklist_25":{"run_date":"2026-07-29","hits":8,"misses":14,"disregarded":3,"note":"Canonical 25-SI list; sports limited to My Sports Travel (participant); spectator/prosports/compsports disregarded"},"sis_present":[{"si":"river","name":"river","status":"live"},{"si":"culture","name":"Culture & History","status":"future"},{"si":"deepdive","name":"deepdive","status":"future"},{"si":"culinary","name":"culinary","status":"future"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"future"},{"si":"senior","name":"senior","status":"future"}],"ultra":[{"name":"Aqua Mekong / Scenic Spirit - 5-star small-ship suite","why_ultra":"low-guest design ships Siem Reap<->Phnom Penh, private-excursion fleets, delta-to-Angkor","earning":"cruise-line/host 10-16%","virtuoso_value_add":true,"mor":"commissionable","tier":"ultra","price_band":"~$4,000-9,000+/pp"},{"name":"Raffles Grand Hotel d''Angkor / Amansara - Siem Reap ultra base","why_ultra":"colonial-grand Raffles or Aman''s former royal guesthouse, minutes from Angkor","earning":"consortia/Virtuoso on application","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$400-1,500+/night"},{"name":"A private Angkor day - dawn temples + scholar guide","why_ultra":"Angkor Wat before the gates, a private Khmer-art historian, chauffeured, Tonle Sap sunset","earning":"DMC + venue","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury-ultra","price_band":"on application"}],"source_verified":"2026-07-29","hero":{"query":"The Mekong, Cambodia, Cambodia"},"geo":{"lat":13.3671,"lng":103.8448}}'::jsonb, 5),
  ('mekong-delta-vietnam', '07A', 'The Mekong Delta, Vietnam', 'Vietnam', 'The floating-market doorway to the Mekong', 'live', 'verified', 'venice', 'Southeast Asia', '{"river","culture","deepdive","culinary","adventure","romance","senior"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Southern anchor of the Mekong cruise; embarks Ho Chi Minh City; Vietnam->Cambodia crossing at Tan Chau (open/cruise-used)","Lines: Viking (Magnificent Mekong), Aqua Expeditions, Uniworld, Scenic, Mekong Navigator","Signature river life: Cai Be floating market, Sa Dec colonial town, Ben Tre coconut-farm canals by sampan","Cu Chi tunnels (Vietnam War) the deep-dive stop; cooking classes with delta chefs; morning village cycling","US L1 (Exercise Normal Precautions), issued 2026-06-24, NO carve-outs — cleanest of the 3 Mekong countries","Ultra small-ship (Aqua Mekong ~40 guests); dry season Nov-Apr; currency Vietnamese dong (VND)"],"safety":{"emergency":"113 police / 114 fire / 115 ambulance (Vietnam lines; 112/911 not standard)","hospital":"Ho Chi Minh City international-standard (FV Hospital, Family Medical Practice); delta transfers to HCMC","advisory_level":"L1","malaria":"low in delta tourist corridor (mosquito precautions)","yellow_fever":"not required unless from endemic country","activity_note":"hot/humid year-round (hydrate); sampans small (life vest, follow crew); HCMC traffic dense; wet season May-Oct rain/high water; SE-Asia food-water hygiene; village cycling on unpaved lanes"},"timing":{"peak":"Nov-Apr (dry, cooler — cruise high season; Dec-Feb tightest)","shoulder":"Oct + May (dry-season edges)","green":"Jun-Sep wet season (hot, rain, higher water; best value)","booking_lead":"Mekong cruises 6-12 mo; land + day-cruise 1-4 wk","off_season_specials":"wet-season value cruises + HCMC city-break bookends; operator 2026-28 discounts","event_peaks":"Tet (Lunar New Year ~late Jan-Feb — book ahead, some closures); dry-season cruise window Nov-Apr","campaign_start":"Dry-season cruises by prior spring; Nov-Apr high season by Aug; wet-season value by Apr; watch Tet closures"},"jewels":[{"name":"The Mekong cruise from Ho Chi Minh City","si_tag":"river","status":"live","tier":"premier","price_band":"~$2,500-7,000+/pp/week","timing":"year-round; dry Nov-Apr peak","commission_path":"cruise-line 10-16%","draw_rank":1,"si":"river","when":"year-round; dry Nov-Apr peak","commission":"cruise-line 10-16%"},{"name":"The Cai Be floating market + a delta-village day","si_tag":"river","status":"live","tier":"essential","price_band":"~$25-120/pp","timing":"Nov-Apr","commission_path":"operator/affiliate 8-15%","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"dawn at the floating market, then a sampan into Bến Tre''s coconut canals and a delta homestay lunch — the river-life core","si":"river","blurb":"dawn at the floating market, then a sampan into Bến Tre''s coconut canals and a delta homestay lunch — the river-life core","when":"Nov-Apr","commission":"operator/affiliate 8-15%"},{"name":"The Tan Chau border reach","si_tag":"river","status":"live","tier":"premier","price_band":"within cruise","timing":"Nov-Apr","commission_path":"cruise-line","draw_rank":3,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The Vietnam→Cambodia cruise crossing runs via Tân Châu — open and cruise-used; the delta connects straight to the Cambodian Mekong leg","si":"river","blurb":"The Vietnam→Cambodia cruise crossing runs via Tân Châu — open and cruise-used; the delta connects straight to the Cambodian Mekong leg","when":"Nov-Apr","commission":"cruise-line"},{"name":"Sa Dec + the colonial delta","si_tag":"culture","status":"future","tier":"essential","price_band":"~$20-90","timing":"Nov-Apr","commission_path":"operator on guided walk","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the river town of colonial shophouses and flower gardens, plus Cù Lao Giêng''s colonial architecture","si":"culture","blurb":"the river town of colonial shophouses and flower gardens, plus Cù Lao Giêng''s colonial architecture","when":"Nov-Apr","commission":"operator on guided walk"},{"name":"The floating markets + river life","si_tag":"culture","status":"future","tier":"essential","price_band":"~$20-75","timing":"Nov-Apr","commission_path":"operator/affiliate","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Cái Bè and the delta''s water-borne commerce — markets, stilt houses, coconut and rice-paper craft along the canals","si":"culture","blurb":"Cái Bè and the delta''s water-borne commerce — markets, stilt houses, coconut and rice-paper craft along the canals","when":"Nov-Apr","commission":"operator/affiliate"},{"name":"The Cu Chi tunnels","si_tag":"deepdive","status":"future","tier":"essential","price_band":"~$20-90/pp","timing":"Nov-Apr","commission_path":"op 10-15%","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the underground network near Ho Chi Minh City, the Vietnam War history stop that opens many delta itineraries","si":"deepdive","blurb":"the underground network near Ho Chi Minh City, the Vietnam War history stop that opens many delta itineraries","when":"Nov-Apr","commission":"op 10-15%"},{"name":"A cooking class with a delta chef","si_tag":"culinary","status":"future","tier":"essential","price_band":"~$30-120/pp","timing":"Nov-Apr","commission_path":"venue/DMC 10-15%","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"market-to-table Mekong cooking — pick produce at a floating market, cook it aboard or in a village kitchen","si":"culinary","blurb":"market-to-table Mekong cooking — pick produce at a floating market, cook it aboard or in a village kitchen","when":"Nov-Apr","commission":"venue/DMC 10-15%"},{"name":"Fruit orchards + a Ho Chi Minh City street-food graze","si_tag":"culinary","status":"future","tier":"essential","price_band":"~$20-70/pp","timing":"Nov-Apr","commission_path":"bundle/venue","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the delta''s tropical-fruit larder plus the gateway city''s legendary street food — phở, bánh mì, cơm tấm","si":"culinary","blurb":"the delta''s tropical-fruit larder plus the gateway city''s legendary street food — phở, bánh mì, cơm tấm","when":"Nov-Apr","commission":"bundle/venue"},{"name":"Village cycling + sampan the canals","si_tag":"globaladv","status":"future","tier":"essential","price_band":"~$25-90/pp","timing":"year-round","commission_path":"operator/affiliate 10-15%","draw_rank":1,"hook":"the delta''s active morning — cycle unpaved village lanes past orchards, then paddle a sampan through the narrow canals","si":"adventure","blurb":"the delta''s active morning — cycle unpaved village lanes past orchards, then paddle a sampan through the narrow canals","when":"year-round","commission":"operator/affiliate 10-15%"},{"name":"A small-ship river honeymoon","si_tag":"romance","status":"future","tier":"premier","price_band":"~$3,000-7,000+/pp","timing":"dry Nov-Apr ideal","commission_path":"cruise-line/host 10-16%","draw_rank":1,"hook":"a suite on an Aqua Mekong-class 5-star ship, private sampan sunset and a delta cooking dinner — a quiet, unusual river honeymoon","si":"romance","blurb":"a suite on an Aqua Mekong-class 5-star ship, private sampan sunset and a delta cooking dinner — a quiet, unusual river honeymoon","when":"dry Nov-Apr ideal","commission":"cruise-line/host 10-16%"},{"name":"The low-exertion river cruise","si_tag":"senior","status":"future","tier":"comfort","price_band":"~$2,500-5,000/pp","timing":"dry Nov-Apr ideal","commission_path":"cruise-line/DMC 10-16%","draw_rank":1,"hook":"a gentle, all-in small-ship cruise with step-light delta excursions — a natural fit for the river-cruise senior demographic, HCMC the easy gateway","si":"senior","blurb":"a gentle, all-in small-ship cruise with step-light delta excursions — a natural fit for the river-cruise senior demographic, HCMC the easy gateway","when":"dry Nov-Apr ideal","commission":"cruise-line/DMC 10-16%"}],"faq":[{"q":"Is the Mekong Delta / Vietnam safe to visit right now?","a":"Yes — freely bookable, and the cleanest of the three Mekong countries. Vietnam is US Level 1 (Exercise Normal Precautions), issued 24 June 2026 with no carve-outs; the routine cautions are petty theft and dense traffic.","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for in the Mekong Delta?","a":"Not crime - heat, traffic and the water: the delta is hot and humid year-round, Ho Chi Minh City traffic is dense, and canal sampans are small craft (follow crew, wear the life vest). Standard SE-Asia food-and-water hygiene applies.","source":"travel.state.gov","si_tag":"safety"},{"q":"Is the Vietnam-Cambodia border crossing on a Mekong cruise a problem?","a":"No - the cruise river crossing at Tan Chau is open and routinely used by the ships. (Separately, some Cambodia-Thailand land borders are closed - that affects the Cambodia leg, not this Vietnamese one.)","source":"vikingrivercruises.com","si_tag":"river"},{"q":"When is the best time to cruise the Vietnamese Mekong?","a":"Roughly November-April, the drier cooler window, because the May-October wet season brings heavy afternoon rain and higher water - though the delta cruises year-round and high water opens more canals.","source":"aquaexpeditions.com","si_tag":"river"},{"q":"Which lines cruise the Vietnamese Mekong?","a":"Confirmed from Ho Chi Minh City: Viking, Aqua Expeditions, Uniworld, Scenic and Mekong Navigator - most on Vietnam-Cambodia itineraries linking the delta to Phnom Penh and Siem Reap.","source":"vikingrivercruises.com","si_tag":"river"},{"q":"What do you actually see in the Mekong Delta?","a":"River life: the Cai Be floating market, Sa Dec''s colonial streets and flower gardens, Ben Tre''s coconut canals by sampan, cooking classes with delta chefs, and - near the start - the Cu Chi tunnels of the Vietnam War.","source":"uniworld.com","si_tag":"culture"},{"q":"Is the Mekong Delta good for a river-cruise honeymoon or for older travellers?","a":"Yes to both - small-ship 5-star cruising (Aqua Mekong ~40 guests) suits a quiet honeymoon, and the gentle all-in format with step-light excursions and HCMC as an easy gateway fits the river-cruise senior demographic.","source":"aquaexpeditions.com","si_tag":"romance"}],"seo":{"meta_title":"Mekong Delta Vietnam Travel Guide: River Cruises, Floating Markets & Cu Chi","meta_description":"Plan Vietnam''s Mekong Delta — river cruises from Ho Chi Minh City (Viking, Aqua Expeditions, Uniworld, Scenic), Cai Be & Ben Tre by sampan, Sa Dec, cooking classes and the Cu Chi tunnels.","slug":"mekong-delta-vietnam","primary_keyword":"Mekong Delta Vietnam travel guide","long_tail":["Mekong Delta river cruise from Ho Chi Minh City 2026","Cai Be floating market","Ben Tre coconut canals sampan","Cu Chi tunnels tour","Vietnam Cambodia Mekong cruise","Aqua Mekong small-ship"],"search_language":"vi-VN","local_keywords":["Dong bang song Cuu Long","du thuyen song Mekong","cho noi Cai Be","Ben Tre","Sa Dec","dia dao Cu Chi","Thanh pho Ho Chi Minh","Tan Chau"],"hreflang":["en","vi-VN"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-29"},"booking":{"bin":"freely_bookable","level":"L1","codes":[],"advisory_updated":"2026-06-24","consent_flow":false,"note":"Vietnam US L1 (Exercise Normal Precautions), no carve-outs — cleanest of the 3 Mekong countries"},"si_checklist_25":{"run_date":"2026-07-29","hits":8,"misses":14,"disregarded":3,"note":"Canonical 25-SI list; sports limited to My Sports Travel (participant); spectator/prosports/compsports disregarded"},"sis_present":[{"si":"river","name":"river","status":"live"},{"si":"culture","name":"Culture & History","status":"future"},{"si":"deepdive","name":"deepdive","status":"future"},{"si":"culinary","name":"culinary","status":"future"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"romance","name":"Romance, Marriages & Honeymoons","status":"future"},{"si":"senior","name":"senior","status":"future"}],"ultra":[{"name":"Aqua Mekong — 5-star small-ship suite (~40 guests)","why_ultra":"design ship with private-sampan excursion fleet, delta cooking + spa, Vietnam<->Cambodia Mekong","earning":"cruise-line/host 10-16%","virtuoso_value_add":true,"mor":"commissionable","tier":"ultra","price_band":"~$4,000-9,000+/pp"},{"name":"Park Hyatt Saigon / The Reverie — HCMC ultra bookend","why_ultra":"top-tier gateway stay, spa + fine dining in District 1","earning":"consortia/Virtuoso on application","virtuoso_value_add":true,"mor":"commissionable-rack","tier":"ultra","price_band":"~$300-800+/night"},{"name":"A private delta day — chartered sampan + delta chef''s table","why_ultra":"private canal boat + market-to-table lunch, chauffeured from HCMC","earning":"DMC + venue","virtuoso_value_add":false,"mor":"commissionable","tier":"luxury-ultra","price_band":"on application"}],"source_verified":"2026-07-29","hero":{"query":"The Mekong Delta, Vietnam, Vietnam"},"geo":{"lat":10.0341,"lng":105.788}}'::jsonb, 6),
  ('raja-ampat-indonesia', '07A', 'Raja Ampat', 'Indonesia', '*If it''s the richest reef on the planet, manta', 'live', 'verified', 'oceanAerial', 'Raja Ampat — Indonesia (Southwest Papua)', '{"liveaboard","adventure","diveglobal","ocean"}', '{}', '{"comfort","premier"}', null, 'emerging', '{"key_facts":["NW-monsoon liveaboard sea, ~Oct-April (calmest/clearest); avoid Jun-Jul; seasonal inverse of Komodo; water ~28-30C","Three regions: Dampier Strait (Cape Kri - single-dive fish-count record, Blue Magic, Sardine Reef, Manta Sandy), Misool (Boo Windows, Magic Mountain, Four Kings), Wayag/north","Manta cleaning stations: Manta Sandy (Dampier) + Magic Mountain/Shadow Reef (Misool)","Fleet: Raja Ampat Aggressor (reseller line held), Explorer Ventures (reseller line held), Emperor Harmoni/Raja Laut, Master Indo Master, luxury phinisi (Damai/Dewi Nusantara/Mermaid/Arenui/Coralia)","Advisory: State L2 (reissued 30 Apr 2025; only Papua L4 = Central + Highland Papua; Raja Ampat/Southwest Papua outside both; FCDO points Papua caution at the highlands); nearest chamber Waisai but readiness not assured - evac to Manado/Bali; Wayag temporarily closed (verify) - all verified 2026-08-09"],"safety":{"emergency":"112 / 118 ambulance (verify)","hospital":"Waisai (Waigeo) clinic; Sorong for referral; serious care routes to Manado or Bali (verify)","hyperbaric":"Nearest chamber at Waisai (Waigeo), ~2-4h from sites (+62-951-3173358) but readiness NOT assured - no reliably operational chamber in Papua per dive-medicine sources; DAN-documented case evacuated a diver to Bali (~2,000 km, ~7h via Sorong); Manado the other referral. Confirm status + carry evacuation cover (source: papuaparadise.com + stayrajaampat.com, 2026-08-09)","advisory_level":"L2","regional_hazard":"LIVE: Wayag + Manyaifun/Batangpele reported temporarily closed over nickel-mining disputes - verify northern-route access (rajaampatbiodiversity.com, 2026-08-09)","no_fly_after_diving":"18-24h (DAN)","malaria":"present in Raja Ampat/Papua - discuss prophylaxis (verify)","yellow_fever":"only if arriving from an endemic country"},"timing":{"peak":"Oct-Apr (NW monsoon - calmest, clearest)","shoulder":"May & Sep (season edges)","green":"Jun-Aug (SE monsoon; roughest Jun-Jul; boats reposition to Komodo)","booking_lead":"peak preferred vessels ~6-12 months; shoulder nearer term; confirm per-vessel","off_season_specials":"season-edge shoulder weeks lower demand","event_peaks":"Oct-Apr window is the demand season; manta stations run within it","campaign_start":"wet-season fire Jun-Jul (inverse of the Komodo campaign; sell as a paired Indonesian dive year)"},"jewels":[{"name":"Cape Kri (Dampier Strait)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"holds a record for the most fish species on a single dive; the marquee reef dive","bookable_category":"liveaboard berth","commission_path":"fleet-direct (Aggressor/Explorer)","source":"https://www.lagaligoliveaboard.com/top-10-raja-ampat-dive-sites-you-can-only-reach-by-liveaboard/","timing":"Oct-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"holds a record for the most fish species on a single dive; the marquee reef dive","when":"Oct-Apr","commission":"fleet-direct (Aggressor/Explorer)"},{"name":"Blue Magic (Dampier Strait)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"strong-current pinnacle; barracuda, trevally, mantas","bookable_category":"liveaboard berth","commission_path":"fleet-direct","source":"https://www.lagaligoliveaboard.com/top-10-raja-ampat-dive-sites-you-can-only-reach-by-liveaboard/","timing":"Oct-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"strong-current pinnacle; barracuda, trevally, mantas","when":"Oct-Apr","commission":"fleet-direct"},{"name":"Sardine Reef (Dampier Strait)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"dense schooling reef in current","bookable_category":"liveaboard berth","commission_path":"fleet-direct","source":"https://blog.padi.com/liveaboard-trip-raja-ampat/","timing":"Oct-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"dense schooling reef in current","when":"Oct-Apr","commission":"fleet-direct"},{"name":"Manta Sandy (Dampier Strait)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"the northern manta cleaning station","bookable_category":"liveaboard berth","commission_path":"fleet-direct","source":"https://www.lagaligoliveaboard.com/top-10-raja-ampat-dive-sites-you-can-only-reach-by-liveaboard/","si":"liveaboard","blurb":"the northern manta cleaning station","commission":"fleet-direct"},{"name":"Arborek Jetty (Dampier Strait)","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"jetty macro and schooling fish; snorkel-friendly","bookable_category":"liveaboard berth","commission_path":"fleet-direct","source":"https://blog.padi.com/liveaboard-trip-raja-ampat/","timing":"Oct-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"jetty macro and schooling fish; snorkel-friendly","when":"Oct-Apr","commission":"fleet-direct"},{"name":"Mioskon (Dampier Strait)","si_tag":"liveaboard","status":"live","tier":"comfort","hook":"dusk reef, wobbegong sharks","bookable_category":"liveaboard berth","commission_path":"fleet-direct","source":"https://blog.padi.com/liveaboard-trip-raja-ampat/","timing":"Oct-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"dusk reef, wobbegong sharks","when":"Oct-Apr","commission":"fleet-direct"},{"name":"The Passage (Waigeo-Gam)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"a mangrove tidal channel dived like a jungle river","bookable_category":"liveaboard berth","commission_path":"fleet-direct","source":"https://www.lagaligoliveaboard.com/top-10-ra